1	import { hashToken, verify as verifyToken, type Caller } from "./auth.js";
2	import { askFor, fits, framesForGesture, loadoutFor, profileOf, setupFor } from "./control.js";
3	import { askAllowed } from "./asking.js";
4	import { apiGatewayPoster, type Poster } from "./live.js";
5	import { dynamoLive, type LiveStore } from "./live.js";
6	import { dynamoStore, type Ask, type Store } from "./store.js";
7	import { dynamoRaces, type RaceStore } from "./races.js";
8	import { dynamoBilling, featuresFromEnv, grantsOf } from "./billing.js";
9	import { annotate } from "./xray.js";
10	import { randomBytes } from "node:crypto";
11	
12	/**
13	 * The socket's three moments.
14	 *
15	 * Connect: the token rides in the query string, because a browser's
16	 * WebSocket cannot set a header. It is checked the same way the HTTP API
17	 * checks a bearer, and a bad one is refused before the socket opens.
18	 * Message: the one thing a device says is which session it is watching;
19	 * it must be a member, and a session it may not see is ignored without
20	 * saying whether it exists. Disconnect: the rows go.
21	 *
22	 * A run shared by link admits a socket with no account: `?t=<token>&run=<id>`
23	 * opens a connection that watches that run and nothing else, and says
24	 * nothing it is told.
25	 *
26	 * Nothing else. Moves still travel over HTTP; the socket is a doorbell.
27	 */
28	
29	export interface WsEvent {
30	  requestContext: { routeKey: string; connectionId: string };
31	  queryStringParameters?: Record<string, string | undefined>;
32	  body?: string;
33	  isBase64Encoded?: boolean;
34	}
35	
36	export interface WsDeps {
37	  live: LiveStore;
38	  /** A way to post to connections; absent in a test that only checks routing. */
39	  poster?: Poster;
40	  store: Pick<Store, "getSession" | "streamKeyOwner" | "manifest" | "getSnapshot" | "addAsk" | "updateSession">;
41	  races: Pick<RaceStore, "getRace">;
42	  verify: (authorization: string | undefined) => Promise<Caller>;
43	  now?: () => string;
44	  /**
45	   * Whether this account may drive a run from outside it. Absent where
46	   * plans are off, which is the same answer as yes.
47	   */
48	  entitled?: (sub: string) => Promise<boolean>;
49	}
50	
51	interface WsResult {
52	  statusCode: number;
53	  body?: string;
54	}
55	
56	/**
57	 * A socket opened by something that drives a game rather than draws a
58	 * scoreboard.
59	 *
60	 * It arrives on the same addresses as every other watcher, with the same
61	 * keys, because what it is allowed to see is exactly what a watcher is
62	 * allowed to see. What it asks for in addition is to be told in
63	 * operations, and to say which player it is sitting in front of.
64	 */
65	function attachedOf(event: WsEvent, run: string): { control: true; seat?: string; run: string } | undefined {
66	  if (event.queryStringParameters?.["as"] !== "control") return undefined;
67	  const raw = (event.queryStringParameters?.["seat"] ?? "").trim().slice(0, 40);
68	  return { control: true, ...(raw ? { seat: raw } : {}), run };
69	}
70	
71	/**
72	 * A socket that presses rather than draws.
73	 *
74	 * It signs in as the account, the way the app's own devices do, because
75	 * what it may do is what the owner may do. It names no run at connect: it
76	 * is told which runs are being held, and picks. A link's token and a
77	 * stream key are refused here, which is why this is read only on the
78	 * signed-in branch below.
79	 */
80	function deckOf(event: WsEvent): { deck: true } | undefined {
81	  return event.queryStringParameters?.["as"] === "deck" ? { deck: true } : undefined;
82	}
83	
84	/**
85	 * Whether this watcher is a device that could take a press.
86	 *
87	 * A link's socket and a scene's are not; an attached tool is told in
88	 * operations and writes nothing; a deck is the thing asking. What is
89	 * left is a signed-in device with the run open, which is the page.
90	 */
91	function writes(w: { sub: string; control?: boolean; deck?: boolean }): boolean {
92	  return !w.control && !w.deck && !w.sub.startsWith("public:") && !w.sub.startsWith("stream:");
93	}
94	
95	export async function route(event: WsEvent, deps: WsDeps): Promise<WsResult> {
96	  const { routeKey, connectionId } = event.requestContext;
97	  const now = deps.now ?? (() => new Date().toISOString());
98	  // The socket has no method, only which of its three moments this is.
99	  annotate({ method: "WS", route: routeKey });
100	
101	  /**
102	   * The account's runs that something is holding open.
103	   *
104	   * Not the run that moved most recently, which is all a watch key can
105	   * know: a deck presses, and a press wants a device on the other end.
106	   * The newest twenty are considered, because an account's manifest is
107	   * every run it has ever played and a deck's picker is a short list.
108	   */
109	  const heldRuns = async (sub: string) => {
110	    const { sessions } = await deps.store.manifest(sub);
111	    const mine = sessions
112	      .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt)
113	      .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0))
114	      .slice(0, 20);
115	    const held = await Promise.all(mine.map(async (p) => ((await deps.live.watchers(p.id)).some(writes) ? p : null)));
116	    return held
117	      .filter((p): p is (typeof mine)[number] => p !== null)
118	      .map((p) => ({
119	        id: p.id,
120	        ...(p.name ? { name: p.name } : {}),
121	        ...(p.packTitle ? { packTitle: p.packTitle } : {}),
122	        held: true as const,
123	      }));
124	  };
125	
126	  /**
127	   * Said to an account's decks whenever the held set changes, and once on
128	   * connect, which is the same message: a deck comes up before anything is
129	   * running, so a list fetched once would stay empty all evening.
130	   */
131	  const tellDecks = async (sub: string, only?: string): Promise<void> => {
132	    const poster = deps.poster;
133	    if (!poster) return;
134	    // Everything in here, one guard: a deck that cannot be given its list
135	    // right now is still connected and hears the next push. A rejection
136	    // out of `manifest` or `watchers` must not turn a $connect into a 500,
137	    // which would refuse the deck outright.
138	    try {
139	      const decks = only ? [{ connectionId: only }] : await deps.live.decksOf(sub);
140	      if (decks.length === 0) return;
141	      const line = JSON.stringify({ t: "runs", runs: await heldRuns(sub) });
142	      for (const d of decks) {
143	        if ((await poster.post(d.connectionId, line)) === "gone") await deps.live.disconnect(d.connectionId);
144	      }
145	    } catch (error) {
146	      console.error("live: could not say which runs are held", error);
147	    }
148	  };
149	
150	  if (routeKey === "$connect") {
151	    const t = event.queryStringParameters?.["t"];
152	    const run = event.queryStringParameters?.["run"];
153	    if (t && run) {
154	      const session = await deps.store.getSession(run);
155	      if (!session || session.meta.deletedAt || !session.meta.publicTokenHash || hashToken(t) !== session.meta.publicTokenHash)
156	        return { statusCode: 401, body: "not shared" };
157	      const who = `public:${run}`;
158	      const attached = attachedOf(event, run);
159	      await deps.live.connect(connectionId, who, now(), attached);
160	      await deps.live.watch(connectionId, run, who, now(), attached);
161	      return { statusCode: 200 };
162	    }
163	    /**
164	     * A scene's socket, opened on the account's watch key.
165	     *
166	     * The address in a browser source or a bot's client is set up once and
167	     * lives for months, so it cannot name a run: it names the account, and
168	     * this finds the run. Of the runs open to watchers, the one moved most
169	     * recently, which is the one being played.
170	     *
171	     * Which run it watches is settled when it connects. A socket open
172	     * across the start of a new run goes on watching the old one until it
173	     * is opened again; the bot hears `run-ended` on the old one, which is
174	     * the moment to reconnect.
175	     */
176	    const k = event.queryStringParameters?.["k"];
177	    if (k) {
178	      const owner = await deps.store.streamKeyOwner(hashToken(k));
179	      // A press key belongs in a bot's settings, never in a scene.
180	      if (!owner || owner.kind !== "watch") return { statusCode: 401, body: "not a key for watching" };
181	      const named = (event.queryStringParameters?.["run"] ?? "").trim();
182	      const { sessions } = await deps.store.manifest(owner.sub);
183	      const live = sessions
184	        .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt && (!named || p.id === named))
185	        .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
186	      let watching: string | null = null;
187	      for (const p of live)
188	        if ((await deps.store.getSession(p.id))?.meta.publicTokenHash) {
189	          watching = p.id;
190	          break;
191	        }
192	      if (!watching) return { statusCode: 401, body: "no run is open to watch" };
193	      const who = `stream:${owner.sub}`;
194	      const attached = attachedOf(event, watching);
195	      await deps.live.connect(connectionId, who, now(), attached);
196	      await deps.live.watch(connectionId, watching, who, now(), attached);
197	      return { statusCode: 200 };
198	    }
199	    const token = event.queryStringParameters?.["token"];
200	    let caller: Caller;
201	    try {
202	      caller = await deps.verify(token ? `Bearer ${token}` : undefined);
203	    } catch {
204	      return { statusCode: 401, body: "sign in first" };
205	    }
206	    // A deck is answered once it speaks, below: the gateway refuses a post
207	    // to a connection whose $connect has not yet returned, and a refusal
208	    // here would read as the deck having gone.
209	    await deps.live.connect(connectionId, caller.sub, now(), deckOf(event));
210	    return { statusCode: 200 };
211	  }
212	
213	  /**
214	   * Who has a tool on the game right now, said to everyone watching.
215	   *
216	   * The whole set every time rather than a joining and a leaving. A table
217	   * that missed one message would otherwise show a tool that went home an
218	   * hour ago, or miss one that is about to be sent a curse, and there is
219	   * no cheap way to notice you missed it. A list is idempotent; a delta is
220	   * a thing to keep in step.
221	   */
222	  const tellWhoIsAttached = async (run: string): Promise<void> => {
223	    const poster = deps.poster;
224	    if (!poster) return;
225	    const watching = await deps.live.watchers(run);
226	    const tools = watching.filter((w) => w.control).map((w) => ({ ...(w.seat ? { seat: w.seat } : {}), ...(w.app ? { app: w.app } : {}) }));
227	    const decks = watching.filter((w) => w.deck).length;
228	    const line = JSON.stringify({ t: "gesture", id: run, kind: "tools", data: { tools, count: tools.length, decks }, at: now() });
229	    for (const w of watching) {
230	      // A tool is told in operations, never in words about itself.
231	      if (w.control) continue;
232	      try {
233	        if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
234	      } catch (error) {
235	        console.error("live: could not say who is attached", error);
236	      }
237	    }
238	  };
239	
240	  if (routeKey === "$disconnect") {
241	    // Read before it goes: a tool leaving is news, and afterwards there is
242	    // nothing left to say which run it was on.
243	    const leaving = await deps.live.connection(connectionId);
244	    await deps.live.disconnect(connectionId);
245	    if (leaving?.control && leaving.run) await tellWhoIsAttached(leaving.run);
246	    // A deck leaving its run is news the same way a tool leaving is: the
247	    // page is told, as it was told the deck came on.
248	    if (leaving?.deck && leaving.run) await tellWhoIsAttached(leaving.run);
249	    // A page closing may have been the last thing holding a run, and a deck
250	    // whose keys still look live is worse than one that says so.
251	    if (leaving && !leaving.deck && writes(leaving)) await tellDecks(leaving.sub);
252	    return { statusCode: 200 };
253	  }
254	
255	  // $default: a message.
256	  const conn = await deps.live.connection(connectionId);
257	  if (!conn) return { statusCode: 401, body: "unknown connection" };
258	  let message: unknown;
259	  try {
260	    const raw = event.isBase64Encoded ? Buffer.from(event.body ?? "", "base64").toString("utf8") : (event.body ?? "");
261	    message = JSON.parse(raw);
262	  } catch {
263	    return { statusCode: 400, body: "JSON, please" };
264	  }
265	  if (!message || typeof message !== "object") return { statusCode: 400, body: "an object" };
266	  const m = message as Record<string, unknown>;
267	
268	  /**
269	   * A deck saying it is here.
270	   *
271	   * The one thing a deck asks for. It cannot be told at connect, since the
272	   * gateway takes no post for a connection until $connect has answered, so
273	   * the list it needs to pick a run comes the moment it speaks, and again
274	   * whenever the set of held runs changes.
275	   */
276	  if (conn.deck && m["t"] === "hello") {
277	    await tellDecks(conn.sub, connectionId);
278	    return { statusCode: 200 };
279	  }
280	
281	  /**
282	   * A tool saying what it is and what it can do.
283	   *
284	   * The one message an attached tool sends, and the only one any of them
285	   * may: what comes back is the run's own terms, the settings it wants in
286	   * force before anything is rolled. Everything else it hears is sent
287	   * because the table moved, never because it asked.
288	   *
289	   * What the tool can do is not read here. A source that only ever sends
290	   * what a profile names cannot send an operation an old build lacks, and
291	   * a build that receives one refuses it by name, which is the answer in
292	   * both directions.
293	   */
294	  if (conn.control && m["t"] === "hello" && conn.run) {
295	    // What it calls itself is remembered, because a profile written for
296	    // one program must not drive another that happens to share an
297	    // operation name.
298	    const app = typeof m["app"] === "string" ? m["app"].trim().slice(0, 64) : "";
299	    await deps.live.watch(connectionId, conn.run, conn.sub, now(), {
300	      control: true,
301	      ...(conn.seat ? { seat: conn.seat } : {}),
302	      ...(app ? { app } : {}),
303	      run: conn.run,
304	    });
305	
306	    // The table hears that somebody's game is on the other end of this.
307	    // Said here rather than at connect, because until the hello arrives
308	    // there is no seat and no name to say, and a row with neither is not
309	    // worth drawing.
310	    await tellWhoIsAttached(conn.run);
311	
312	    const poster = deps.poster;
313	    if (!poster) return { statusCode: 200 };
314	    const snapshot = await deps.store.getSnapshot(conn.run);
315	    const profile = snapshot ? profileOf(snapshot.snapshot) : null;
316	    // Told rather than left silent: a tool sitting there doing nothing
317	    // is the most confusing thing this could do. Which is what it did
318	    // until now in the one case that matters most, the run it found
319	    // having no rules at all: an address names an account and the
320	    // server picks the run, so a tool can attach perfectly to a run
321	    // nobody is playing and report itself connected for ever.
322	    const session = await deps.store.getSession(conn.run);
323	    const which = session?.meta.packTitle ?? "a run";
324	    /**
325	     * Who has already had the parts of the terms that are given once.
326	     *
327	     * A seat, or the table where a tool named none. The terms go out on
328	     * every attach, because a tool that restarted is holding none of
329	     * them and a setting applied twice is the same setting. A gift is
330	     * not: a run whose terms hand over runes or an item handed them over
331	     * again on every reconnect, and by the third one it is a different
332	     * game. So the run remembers, and those parts are left out.
333	     */
334	    const whose = conn.seat || "the table";
335	    const given = session?.meta.termsGiven ?? [];
336	    const gotLoadout = session?.meta.loadoutGiven ?? [];
337	    /*
338	     * Two effects, not one. The pack's terms and the loadout chosen for
339	     * this run are one list in the profile and go out as two applies,
340	     * because the loadout has a button that re-sends it and a tool
341	     * re-applying an id takes the old one off first.
342	     */
343	    let terms: { frame: string; gave: boolean } | null = null;
344	    let loadout: { frame: string; gave: boolean } | null = null;
345	    const lines: string[] = [];
346	    if (!profile) {
347	      lines.push(
348	        JSON.stringify({
349	          t: "note",
350	          text: `Attached to ${which}, which has no rules for a tool. An address finds the most recently played run that is open to watchers; if that is not the one you are playing, open that one to watchers and connect again.`,
351	        }),
352	      );
353	    } else if (!fits(profile, app || undefined)) {
354	      lines.push(
355	        JSON.stringify({
356	          t: "note",
357	          text: `${which} is set up for ${profile.tool}, so nothing here will reach ${app || "a tool that did not say what it is"}.`,
358	        }),
359	      );
360	    } else {
361	      terms = setupFor(profile, given.includes(whose));
362	      loadout = loadoutFor(profile, gotLoadout.includes(whose));
363	      if (terms) lines.push(terms.frame);
364	      if (loadout) lines.push(loadout.frame);
365	    }
366	    for (const line of lines) {
367	      if ((await poster.post(connectionId, line)) === "gone") {
368	        await deps.live.disconnect(connectionId);
369	        return { statusCode: 200 };
370	      }
371	    }
372	    // Remembered only once it has actually gone out. A post that failed
373	    // is a tool that never got its terms, and marking it given would
374	    // leave the next attach short of them for the rest of the run.
375	    const patch: { termsGiven?: string[]; loadoutGiven?: string[] } = {};
376	    if (terms?.gave && !given.includes(whose)) patch.termsGiven = [...given, whose];
377	    if (loadout?.gave && !gotLoadout.includes(whose)) patch.loadoutGiven = [...gotLoadout, whose];
378	    if (patch.termsGiven || patch.loadoutGiven) await deps.store.updateSession(conn.run, now(), patch);
379	    return { statusCode: 200 };
380	  }
381	
382	  /**
383	   * A tool saying what happened in the game.
384	   *
385	   * The one thing that travels the other way. It is a mention rather than
386	   * a command: it becomes an ask, exactly as a viewer pressing a button
387	   * does, and the table still decides. Which is why this needs the host
388	   * to have switched asks on, and is refused as politely as anything else
389	   * when they have not.
390	   */
391	  if (conn.control && m["t"] === "event" && conn.run) {
392	    /**
393	     * Something the game said. Dropped for several good reasons, and it
394	     * used to be dropped in silence: every one of these answered 200, the
395	     * tool logged that it had said so, and a death counted nowhere. The
396	     * tool is told now, because "it went nowhere and here is why" is the
397	     * one thing it cannot work out from its end.
398	     */
399	    const drop = async (why: string): Promise<WsResult> => {
400	      const poster = deps.poster;
401	      if (poster) {
402	        try {
403	          await poster.post(connectionId, JSON.stringify({ t: "note", text: why }));
404	        } catch (error) {
405	          console.error("live: could not say why an event went nowhere", error);
406	        }
407	      }
408	      return { statusCode: 200 };
409	    };
410	    const meant = askFor(String(m["kind"] ?? ""));
411	    if (!meant) return drop(`This run has nothing it calls "${String(m["kind"] ?? "")}", so nothing was counted.`);
412	    const session = await deps.store.getSession(conn.run);
413	    if (!session || session.meta.deletedAt || session.meta.endedAt) return drop("That run has ended, so nothing was counted.");
414	    // Taking asks stays the host's word, per run, the same as it is for
415	    // chat. A tool cannot switch it on by being attached.
416	    if (!session.meta.askPolicy)
417	      return drop(
418	        "This run is not taking asks, so nothing was counted. Switch it on under Settings, Stream, Chat, and the game's word counts from then on.",
419	      );
420	    const who = conn.seat || "the game";
421	    const at = now();
422	    if (!askAllowed(conn.run, who, Date.parse(at)).ok) return drop("Too many, too quickly: this one was not counted.");
423	    const ask: Ask = { id: randomBytes(6).toString("hex"), kind: "move", move: meant.move, name: who, via: "the game", at };
424	    await deps.store.addAsk(conn.run, ask);
425	    const poster = deps.poster;
426	    // And when it did land, which of the two landings it was: taken, or
427	    // put in front of somebody. A tool that cannot tell those apart from
428	    // having been ignored is a tool nobody believes.
429	    if (poster) {
430	      const heard =
431	        session.meta.askPolicy === "auto" ? "Counted." : "Said. It is in the run's asks, waiting for whoever is at the table to take it.";
432	      try {
433	        await poster.post(connectionId, JSON.stringify({ t: "note", text: heard }));
434	      } catch (error) {
435	        console.error("live: could not say an event landed", error);
436	      }
437	    }
438	    if (poster) {
439	      const line = JSON.stringify({
440	        t: "gesture",
441	        id: conn.run,
442	        kind: "ask",
443	        data: { ask: ask.id, kind: ask.kind, move: ask.move, name: who, via: ask.via, policy: session.meta.askPolicy },
444	        at,
445	      });
446	      for (const w of await deps.live.watchers(conn.run)) {
447	        if (w.control) continue;
448	        try {
449	          if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
450	        } catch (error) {
451	          console.error("live: could not pass an ask on", error);
452	        }
453	      }
454	    }
455	
456	    return { statusCode: 200 };
457	  }
458	
459	  /**
460	   * A deck pressing something.
461	   *
462	   * The server checks who is asking and finds the devices that could take
463	   * it; it does not read the press. What may be pressed is the run's
464	   * business, and the run is the only thing holding the pack and the log.
465	   *
466	   * Nothing is stored. A press is worth exactly as much as the moment it
467	   * was made in: `seq` names the offer it was drawn from, and the writing
468	   * device refuses one it has already moved past. Durability would buy a
469	   * press that lands after the reason for it has gone.
470	   */
471	  if (conn.deck && m["t"] === "drive") {
472	    const poster = deps.poster;
473	    const ref = typeof m["ref"] === "string" ? m["ref"].slice(0, 64) : "";
474	    const run = typeof m["run"] === "string" ? m["run"] : "";
475	    const refuse = async (say: string): Promise<WsResult> => {
476	      if (poster) {
477	        try {
478	          await poster.post(connectionId, JSON.stringify({ t: "drove", ref, ok: false, say }));
479	        } catch (error) {
480	          console.error("live: could not refuse a press", error);
481	        }
482	      }
483	      return { statusCode: 200 };
484	    };
485	    if (!ref || !run) return { statusCode: 400, body: "a press has a run and a ref" };
486	    /**
487	     * Two reads over the network before a press goes anywhere, and either
488	     * can fail on its own. A rejection used to throw past this branch to
489	     * the handler's 500, which posts nothing at all: the deck was left
490	     * holding a press with no verdict, and no way to tell that from one
491	     * still in flight. It is told, in words that say to try again.
492	     */
493	    let session: Awaited<ReturnType<typeof deps.store.getSession>>;
494	    try {
495	      session = await deps.store.getSession(run);
496	    } catch (error) {
497	      console.error("live: could not read the run behind a press", error);
498	      return refuse("Could not check that right now.");
499	    }
500	    if (!session || session.meta.deletedAt || session.meta.ownerSub !== conn.sub) return refuse("That run is not yours to press.");
501	    if (session.meta.endedAt) return refuse("That run has ended.");
502	    if (deps.entitled) {
503	      let allowed: boolean;
504	      try {
505	        allowed = await deps.entitled(conn.sub);
506	      } catch (error) {
507	        console.error("live: could not read the plan behind a press", error);
508	        return refuse("Could not check that right now.");
509	      }
510	      if (!allowed) return refuse("Driving a run from a deck is part of Plus.");
511	    }
512	
513	    /**
514	     * The one device that takes it.
515	     *
516	     * A press is an ordinary move by the owner's own hand, and a move
517	     * happens once. Posted to every writing watcher it happened as many
518	     * times as the account had the run open: a second device of the
519	     * owner's appended the same event again, and another member's browser
520	     * appended it under their name, whose verdict is then dropped on the
521	     * way back and never reaches the deck at all.
522	     *
523	     * So: the account's own devices only, and of those the one that
524	     * opened the run last, which is the one in front of whoever is
525	     * playing. Ties by connection id, so two watches in the same
526	     * millisecond still settle on the same device every time.
527	     */
528	    const writers = (await deps.live.watchers(run))
529	      .filter((w) => writes(w) && w.sub === conn.sub)
530	      .sort((a, b) => (a.watchedAt === b.watchedAt ? (a.connectionId < b.connectionId ? -1 : 1) : a.watchedAt > b.watchedAt ? -1 : 1))
531	      .slice(0, 1);
532	    if (writers.length === 0) return refuse("Nothing is holding that run.");
533	    if (!poster) return { statusCode: 200 };
534	
535	    const line = JSON.stringify({
536	      t: "drive",
537	      from: connectionId,
538	      run,
539	      seq: typeof m["seq"] === "number" ? m["seq"] : 0,
540	      ref,
541	      press: String(m["press"] ?? ""),
542	      ...(typeof m["move"] === "string" ? { move: m["move"] } : {}),
543	      ...(m["answer"] && typeof m["answer"] === "object" ? { answer: m["answer"] } : {}),
544	    });
545	    for (const w of writers) {
546	      try {
547	        if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
548	      } catch (error) {
549	        console.error("live: could not pass a press on", error);
550	      }
551	    }
552	    return { statusCode: 200 };
553	  }
554	
555	  /**
556	   * The verdict, on its way back to the one deck that asked.
557	   *
558	   * The deck's connection id came out with the press and goes back with
559	   * the answer, so the server keeps no record of who asked for what. It is
560	   * checked before it is posted to: a member may only answer a deck of
561	   * their own account.
562	   */
563	  if (m["t"] === "drove" && typeof m["to"] === "string") {
564	    // A link's socket and a scene's have no account of their own to share
565	    // with a deck, so no `sub` of theirs can ever match one; said outright
566	    // rather than left to fall out of the comparison below.
567	    if (conn.sub.startsWith("public:") || conn.sub.startsWith("stream:")) return { statusCode: 200 };
568	    const poster = deps.poster;
569	    if (!poster) return { statusCode: 200 };
570	    const target = await deps.live.connection(m["to"]);
571	    if (!target || !target.deck || target.sub !== conn.sub) return { statusCode: 200 };
572	    const line = JSON.stringify({
573	      t: "drove",
574	      ref: typeof m["ref"] === "string" ? m["ref"] : "",
575	      ok: m["ok"] === true,
576	      ...(typeof m["say"] === "string" ? { say: m["say"] } : {}),
577	      // What the run reads at now that the press has landed, where the
578	      // page said: the doorbell that would otherwise carry it is a sync
579	      // away, and a deck pressing twice inside that window named a seq
580	      // the page had already moved past.
581	      ...(typeof m["seq"] === "number" ? { seq: m["seq"] } : {}),
582	    });
583	    try {
584	      if ((await poster.post(m["to"], line)) === "gone") await deps.live.disconnect(m["to"]);
585	    } catch (error) {
586	      console.error("live: could not pass a verdict back", error);
587	    }
588	    return { statusCode: 200 };
589	  }
590	
591	  // A link's socket, and a scene's, watch the one run they were opened for
592	  // and take no requests.
593	  if (conn.sub.startsWith("public:") || conn.sub.startsWith("stream:")) return { statusCode: 200 };
594	  // A gesture: something happening at the table that is not a move, dice
595	  // in the air, a step opened, a card turned, passed straight on to
596	  // everyone watching the run and kept nowhere. Only a member sends one,
597	  // it is small, and its kind is a short word the app gives meaning to.
598	  if (m["t"] === "gesture" && typeof m["id"] === "string" && typeof m["kind"] === "string") {
599	    const id = m["id"];
600	    const kind = m["kind"];
601	    if (id.length > 200 || !/^[a-z][a-z0-9-]{0,31}$/.test(kind)) return { statusCode: 400, body: "a gesture has an id and a kind" };
602	    const data = m["data"] !== undefined && typeof m["data"] === "object" && m["data"] !== null ? m["data"] : {};
603	    if (JSON.stringify(data).length > 2000) return { statusCode: 400, body: "a gesture is small" };
604	    const session = await deps.store.getSession(id);
605	    const member = session && !session.meta.deletedAt ? session.members.find((x) => x.sub === conn.sub) : undefined;
606	    if (!member) return { statusCode: 200 };
607	    const line = JSON.stringify({ t: "gesture", id, kind, data, ...(member.name ? { from: member.name } : {}), at: now() });
608	    const poster = deps.poster;
609	
610	    /**
611	     * The loadout, handed out again on purpose.
612	     *
613	     * Every other gesture is passed on. This one means something to the
614	     * server, because the thing standing in the way of handing a loadout
615	     * out twice is a record the server keeps.
616	     *
617	     * `loadoutGiven` exists so that a tool which dropped and reconnected
618	     * is not given the runes again, and it has to go on doing that. But
619	     * a run whose host has picked a different loadout and pressed the
620	     * button is not a reconnect; it is somebody deciding that this table
621	     * is playing with different gear from now on. So the record is
622	     * cleared here and rebuilt from what actually goes out, and a
623	     * reconnect a second later is short of the gifts exactly as before.
624	     *
625	     * The loadout only. The pack's terms are a separate effect and are
626	     * not re-sent: the button is under a list of loadouts and says it
627	     * hands out the loadout, and sending the terms with it handed over
628	     * the pack's own gifts a second time as well.
629	     *
630	     * The owner only. Every member can send a gesture, and that is right
631	     * for dice in the air and a step opening; handing somebody a hundred
632	     * and twenty thousand runes is not something one player at the table
633	     * should be able to do to the others.
634	     *
635	     * Asked of the run rather than of the member row. Both say the same
636	     * thing today, and the run is the one that says it first: a member
637	     * row carries whatever was written into it when somebody joined.
638	     */
639	    if (kind === "setup") {
640	      if (session?.meta.ownerSub !== conn.sub) return { statusCode: 200 };
641	      if (!poster) return { statusCode: 200 };
642	      const watchers = await deps.live.watchers(id);
643	      const attached = watchers.filter((w) => w.control);
644	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
645	      const gave: string[] = [];
646	      await Promise.all(
647	        watchers.map(async (w) => {
648	          // The table is told in words that it happened; a tool is told
649	          // in operations, which is the same split as everywhere else.
650	          let out = w.connectionId === connectionId ? null : line;
651	          if (w.control) {
652	            if (!profile || !fits(profile, w.app)) return;
653	            // `false`, because being handed one is the whole point: the
654	            // record that would hold the gifts back has just been dropped.
655	            const loadout = loadoutFor(profile, false);
656	            if (!loadout) return;
657	            out = loadout.frame;
658	            if (loadout.gave) gave.push(w.seat || "the table");
659	          }
660	          if (!out) return;
661	          try {
662	            if ((await poster.post(w.connectionId, out)) === "gone") await deps.live.disconnect(w.connectionId);
663	          } catch (error) {
664	            console.error("live: could not hand out the setup", error);
665	          }
666	        }),
667	      );
668	      // Written after the fact, from what went out rather than from what
669	      // was meant to: a tool that was not reachable did not get its
670	      // loadout, and saying it did would leave it short on the next
671	      // attach. `termsGiven` is left alone, because the terms did not
672	      // move.
673	      await deps.store.updateSession(id, now(), { loadoutGiven: [...new Set(gave)] });
674	      return { statusCode: 200 };
675	    }
676	
677	    if (poster) {
678	      const watchers = (await deps.live.watchers(id)).filter((w) => w.connectionId !== connectionId);
679	      // A tool attached to somebody's game is told in operations rather
680	      // than in words, and the profile that decides which is read only
681	      // when one of them is listening.
682	      const attached = watchers.filter((w) => w.control);
683	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
684	      await Promise.all(
685	        watchers.map(async (w) => {
686	          const lines = !w.control ? [line] : profile && fits(profile, w.app) ? framesForGesture(profile, kind, data, w.seat) : [];
687	          for (const out of lines) {
688	            try {
689	              if ((await poster.post(w.connectionId, out)) === "gone") {
690	                await deps.live.disconnect(w.connectionId);
691	                return;
692	              }
693	            } catch (error) {
694	              console.error("live: could not pass a gesture on", error);
695	            }
696	          }
697	        }),
698	      );
699	    }
700	    return { statusCode: 200 };
701	  }
702	  if (m["t"] === "watch" && typeof m["id"] === "string" && m["id"].length > 0 && m["id"].length <= 200) {
703	    // A session or a race that is not theirs to see looks exactly like one
704	    // that is not there: the socket confirms nothing.
705	    const session = await deps.store.getSession(m["id"]);
706	    const inSession = Boolean(session && !session.meta.deletedAt && session.members.some((x) => x.sub === conn.sub));
707	    const race = inSession ? null : await deps.races.getRace(m["id"]);
708	    const inRace = Boolean(race && race.entries.some((e) => e.sub === conn.sub));
709	    if (!inSession && !inRace) return { statusCode: 200 };
710	    await deps.live.watch(connectionId, m["id"], conn.sub, now(), conn.deck ? { deck: true, run: m["id"] } : undefined);
711	    if (conn.deck) {
712	      // Which run it was on before this one, read before the row is
713	      // rewritten: a deck that switches runs leaves the page it left
714	      // showing a deck that is no longer there, and publishing for it.
715	      const left = conn.run;
716	      // A deck is told a run is on it the same way a page is told a tool
717	      // is: the row says so, and the table hears it.
718	      await deps.live.connect(connectionId, conn.sub, now(), { deck: true, run: m["id"] });
719	      if (left && left !== m["id"]) {
720	        // A deck holds one run at a time: the watch it came from goes, or
721	        // the run it left goes on counting a deck that has moved house.
722	        await deps.live.unwatch(connectionId, left);
723	        await tellWhoIsAttached(left);
724	      }
725	    }
726	    // Everyone watching, not only the run a deck just picked. A page that
727	    // opened the run after the deck attached, or came back from a reload,
728	    // otherwise never hears that a deck is on it: the gesture fires when a
729	    // tool says hello and when a deck picks, and a page arriving late
730	    // missed both. It is also what puts the Attached panel back after a
731	    // refresh.
732	    await tellWhoIsAttached(m["id"]);
733	    // A run just came under a device. A deck that has been sitting on "No
734	    // run open" all evening is the one thing waiting to hear it.
735	    await tellDecks(conn.sub);
736	    return { statusCode: 200 };
737	  }
738	  return { statusCode: 400, body: "unknown message" };
739	}
740	
741	/* ---- the Lambda ---------------------------------------------------------- */
742	
743	let deps: WsDeps | undefined;
744	
745	export async function handler(event: WsEvent): Promise<WsResult> {
746	  if (!deps) {
747	    const clientId = process.env["WORKOS_CLIENT_ID"] ?? "";
748	    const cliClientId = process.env["WORKOS_CLI_CLIENT_ID"] ?? "";
749	    const table = process.env["TABLE_NAME"] ?? "";
750	    const gates = process.env["RUNLOG_GATES"] === "on";
751	    const plusFeature = featuresFromEnv(process.env["STRIPE_FEATURES"]).plus;
752	    const billing = dynamoBilling({ table });
753	    deps = {
754	      live: dynamoLive({ table }),
755	      store: dynamoStore({ table, bucket: process.env["BUCKET_NAME"] ?? "" }),
756	      races: dynamoRaces({ table }),
757	      verify: (authorization) => verifyToken(authorization, [clientId, cliClientId]),
758	      ...(process.env["WS_ENDPOINT"] ? { poster: apiGatewayPoster(process.env["WS_ENDPOINT"]) } : {}),
759	      // No token flags are in hand at drive time, only `conn.sub`: the
760	      // kept flags `billing.flags(sub)` do the work a token flag would on
761	      // the API side, and `/api/me` refreshes those on every call the app
762	      // makes, so a comped account is comped here too.
763	      ...(gates ? { entitled: async (sub: string) => (await grantsOf(billing, sub)).includes(plusFeature) } : {}),
764	    };
765	  }
766	  try {
767	    return await route(event, deps);
768	  } catch (error) {
769	    console.error(error);
770	    return { statusCode: 500, body: "something went wrong on this side" };
771	  }
772	}
