              packVersion: "1",
              mode: "race",
              seed: "s",
              ownerSub: "user_1",
              createdAt: "",
              updatedAt: "",
              seq: 1,
            },
            entries: [{ sub: "user_1", joinedAt: "" }],
          };
        if (id === "race2")
          return {
