              packId: "p",
              packVersion: "1",
              mode: "race",
              seed: "s",
              ownerSub: "user_9",
              createdAt: "",
              updatedAt: "",
              seq: 1,
            },
            entries: [{ sub: "user_9", joinedAt: "" }],
          };
        return null;
      },
    },
